<script lang="ts">
  import type { TimelineController } from "../TimelineController";
  import type { DatasetLike } from "../temporal/types";
  let { dataset, controller, time, startIndex = $bindable(0), endIndex = $bindable(0), speed = $bindable(1), playing, selectedId = $bindable<string | null>(null), teamId = $bindable<number | null>(null), minMatchCount = $bindable(1), edgeColorMode = $bindable<"shared" | "winRate" | "recency">("shared"), activeMatchId = $bindable<number | null>(null), onToggle = () => {}, onSeek = () => {}, onPause = () => {}, onSelectPlayer = () => {}, onSelectMatch = () => {} }: { dataset: DatasetLike; controller: TimelineController; time: number; startIndex: number; endIndex: number; speed: number; playing: boolean; selectedId: string | null; teamId: number | null; minMatchCount: number; edgeColorMode: "shared" | "winRate" | "recency"; activeMatchId: number | null; onToggle?: () => void; onSeek?: (index: number) => void; onPause?: () => void; onSelectPlayer?: (id: string) => void; onSelectMatch?: (id: number) => void } = $props();
  const dates = $derived(controller.timeline.dates);
  const currentIndex = $derived(Math.max(0, dates.indexOf(time)));
  const formatDate = (value: number | undefined) => value == null ? "—" : new Date(value).toISOString().slice(0, 10);
  function handleTimelineKey(event: KeyboardEvent): void {
    if (event.key === " " || event.code === "Space") { event.preventDefault(); onToggle(); }
    if (event.key === "Escape") { event.preventDefault(); onPause(); }
  }
  const histogram = $derived.by(() => { const bins = Math.min(64, Math.max(1, dates.length)); return Array.from({ length: bins }, (_, index) => { const from = Math.floor(index * dates.length / bins); const to = Math.max(from + 1, Math.floor((index + 1) * dates.length / bins)); return { index, count: (controller.timeline.matches as readonly { timestamp: number }[]).filter((match) => { const dateIndex = dates.indexOf(match.timestamp); return dateIndex >= from && dateIndex < to; }).length }; }); });
</script>
<section class="absolute inset-x-4 bottom-20 z-10 max-h-[calc(100vh-10rem)] overflow-y-auto rounded-box bg-base-100 p-4 shadow-lg" data-testid="timeline-panel" aria-label="Timeline panel">
  <div class="mb-2 flex h-12 items-end gap-px" aria-label="Match histogram">{#each histogram as bin}<button class="min-w-0 flex-1 bg-primary/70" style={`height:${Math.max(8, bin.count * 4)}px`} aria-label={`${bin.count} matches`} onclick={() => onSeek(Math.min(dates.length - 1, Math.floor(bin.index * dates.length / histogram.length)))}></button>{/each}</div>
  <fieldset class="flex flex-wrap items-center gap-3" aria-label="Timeline playback"><legend class="sr-only">Timeline playback</legend><button class="btn btn-primary min-h-11" aria-pressed={playing} aria-label={playing ? "Pause" : "Play"} onclick={onToggle}>{playing ? "Pause" : "Play"}</button><span class="font-mono text-sm" data-testid="timeline-label">{formatDate(time)}</span><label class="label min-h-11 gap-2"><span>Initial position</span><select class="select select-sm" aria-label="Initial timeline position" onchange={(event) => controller.reset(event.currentTarget.value === "max" ? "max" : "min")}><option value="max">Full at last date</option><option value="min">Empty at first date</option></select></label><label class="label min-h-11 gap-2"><span>Speed</span><select class="select select-sm" aria-label="Timeline speed" value={speed} onchange={(event) => { speed = Number(event.currentTarget.value); controller.setSpeed(speed); }}><option value="0.25">0.25x</option><option value="1">1x</option><option value="4">4x</option></select></label><span class="sr-only" role="status" aria-live="polite">{playing ? "Playing" : "Filter"}: {formatDate(dates[startIndex])} → {formatDate(dates[endIndex])}</span></fieldset>
  <fieldset class="mt-3 grid gap-3 md:grid-cols-3" aria-label="Timeline range"><legend class="px-2 text-sm font-semibold">Timeline range</legend><label class="flex min-h-11 flex-col gap-1"><span>Start date</span><input class="range range-primary" aria-label="Timeline start date" type="range" min="0" max={Math.max(0, dates.length - 1)} step="1" bind:value={startIndex} oninput={onPause} onkeydown={handleTimelineKey} /></label><label class="flex min-h-11 flex-col gap-1"><span>End date</span><input class="range range-primary" aria-label="Timeline end date" type="range" min="0" max={Math.max(0, dates.length - 1)} step="1" bind:value={endIndex} oninput={onPause} onkeydown={handleTimelineKey} /></label><label class="flex min-h-11 flex-col gap-1"><span>Timeline date</span><input class="range range-primary" aria-label="Timeline date" type="range" min="0" max={Math.max(0, dates.length - 1)} step="1" value={currentIndex} oninput={(event) => onSeek(Number(event.currentTarget.value))} onkeydown={handleTimelineKey} /></label></fieldset>
  <fieldset class="mt-3 flex flex-wrap items-center gap-3" aria-label="Timeline filters"><legend class="sr-only">Timeline filters</legend><label class="label gap-2"><span>Team</span><select class="select select-sm" aria-label="Team overlay" bind:value={teamId} onchange={onPause}><option value={null}>All teams</option>{#each Object.entries(dataset.teams ?? {}) as [id, team]}<option value={Number(id)}>{typeof team === "string" ? team : team.name ?? id}</option>{/each}</select></label><label class="label gap-2"><span>Selected player</span><select class="select select-sm" aria-label="Selected player" bind:value={selectedId} onchange={() => selectedId && onSelectPlayer(selectedId)}><option value={null}>No selection</option>{#each Object.entries(dataset.players ?? {}).slice(0, 180) as [id, name]}<option value={id}>{name}</option>{/each}</select></label><label class="label gap-2"><span>Min matches</span><input class="input input-sm w-20" aria-label="Minimum shared matches" type="number" min="1" bind:value={minMatchCount} oninput={onPause} /></label><label class="label gap-2"><span>Edge color</span><select class="select select-sm" aria-label="Edge color overlay" bind:value={edgeColorMode} onchange={onPause}><option value="shared">Shared matches</option><option value="winRate">Win rate</option><option value="recency">Recency</option></select></label></fieldset>
  <div class="mt-3 flex flex-wrap gap-1" data-testid="match-overlay" aria-label="Match list">{#each (dataset.games ?? []).slice(0, 8) as game}<button class="btn btn-xs" class:btn-primary={activeMatchId === game.eventId} onclick={() => onSelectMatch(game.eventId)}>Match {game.eventId}</button>{/each}</div>
</section>
